function showRoom(name){currentRoom=name;$$('.room').forEach(r=>r.classList.toggle('active',r.dataset.roomName===name));$$('[data-room]').forEach(b=>b.classList.toggle('active',b.dataset.room===name));$('.main-nav').classList.remove('open');if(name==='archive')setTimeout(updateArchiveProgress,100);if(name==='route')setTimeout(()=>{routeMap?.resize();focusRealMap(activeStop,true)},120);if(name==='finale')renderRoll(rollIndex);setSoundScene(name)}
