function animateCounts(){$$('[data-count]').forEach(el=>{const goal=+el.dataset.count,start=performance.now(),dur=1400;requestAnimationFrame(function tick(now){const p=Math.min(1,(now-start)/dur),v=Math.floor(goal*(1-Math.pow(1-p,3)));el.textContent=v.toLocaleString()+(goal===380?'+':'');if(p<1)requestAnimationFrame(tick)})})}

let routeMap,mapReady=false,mapMarkers=[];
const routeGeo={type:'Feature',properties:{},geometry:{type:'LineString',coordinates:stops.map(s=>[s.lon,s.lat])}};
function initRouteMap(){if(!window.maplibregl){$('#mapBoard').classList.add('map-failed');return}routeMap=new maplibregl.Map({container:'routeMap',style:'https://tiles.openfreemap.org/styles/fiord',center:[106.4,30.6],zoom:4.25,pitch:34,bearing:-8,attributionControl:false,maxZoom:10});routeMap.addControl(new maplibregl.NavigationControl({showCompass:true,showZoom:true}),'top-right');routeMap.on('load',()=>{routeMap.addSource('long-march',{type:'geojson',data:routeGeo});routeMap.addLayer({id:'route-casing',type:'line',source:'long-march',paint:{'line-color':'#f1dfbd','line-width':8,'line-opacity':.78}});routeMap.addLayer({id:'route-main',type:'line',source:'long-march',paint:{'line-color':'#b51f18','line-width':4,'line-opacity':.96,'line-dasharray':[2,1.35]}});mapReady=true;focusRealMap(activeStop,true)});stops.forEach((s,i)=>{const el=document.createElement('button');el.className='atlas-marker'+(i===0?' active':'');el.innerHTML=`<i></i><span>${s.name}</span>`;el.setAttribute('aria-label',s.name);el.onclick=()=>selectStop(i);mapMarkers.push(el);new maplibregl.Marker({element:el,anchor:'center'}).setLngLat([s.lon,s.lat]).addTo(routeMap)})}
function focusRealMap(i,immediate=false){if(!mapReady)return;const s=stops[i],next=stops[Math.min(i+1,stops.length-1)],bearing=Math.atan2(next.lon-s.lon,next.lat-s.lat)*180/Math.PI;routeMap[immediate?'jumpTo':'flyTo']({center:[s.lon,s.lat],zoom:window.innerWidth<900?5.7:6.25,pitch:52,bearing:Math.max(-32,Math.min(32,bearing)),duration:1150,essential:true})}
stops.forEach((s,i)=>{const chip=document.createElement('button');chip.className='route-chip'+(i===0?' active':'');chip.dataset.index=i;chip.innerHTML=`<span>${String(i+1).padStart(2,'0')} · ${s.date}</span><b>${s.name}</b>`;chip.onclick=()=>selectStop(i);$('#routeScroll').append(chip)});initRouteMap();
function selectStop(i){activeStop=(i+stops.length)%stops.length;const s=stops[activeStop];mapMarkers.forEach((n,j)=>n.classList.toggle('active',j===activeStop));$$('.route-chip').forEach((n,j)=>n.classList.toggle('active',j===activeStop));const chip=$(`.route-chip[data-index="${activeStop}"]`);chip?.scrollIntoView({behavior:'smooth',inline:'center',block:'nearest'});$('#mapCoordinate').textContent=`${s.lat.toFixed(2)}°N · ${s.lon.toFixed(2)}°E`;$('#mapPlace').textContent=s.name;focusRealMap(activeStop);$('#routeFocus').innerHTML=`<small>${String(activeStop+1).padStart(2,'0')} / 11 · ${s.sub}</small><h3>${s.name}</h3><span class="focus-date">${s.date}</span><p class="focus-lead">${s.lead}</p><div class="focus-people"><b>关键人物与群体</b>${s.people.map(n=>`<span>${n.name||n}</span>`).join('')}</div><div class="focus-context"><b>此地发生了什么</b><p>${s.context}</p></div><div class="focus-sacrifice"><b>代价与历史重量</b><p>${s.sacrifice}</p><span>${s.meaning}</span></div><button onclick="openDetail(${activeStop})">进入事件档案 →</button>`}
selectStop(0);$('#routePrev').onclick=()=>selectStop(activeStop-1);$('#routeNext').onclick=()=>selectStop(activeStop+1);

const wall=$('#archiveWall');periodPhotos.forEach((p,i)=>{const a=document.createElement('article');a.className='archive-item archive-authentic';a.innerHTML=`<img src="${p.img}" alt="${p.caption}" loading="lazy"><div class="archive-index">史</div><div class="archive-caption"><small>${p.label}</small><h3>真实历史影像</h3><p>${p.caption}</p><b class="archive-open">史料影像档案</b></div>`;wall.append(a)});stops.forEach((s,i)=>{const a=document.createElement('article');a.className='archive-item';a.innerHTML=`<img src="${s.img}" alt="${s.name}相关${s.type}" loading="lazy"><div class="archive-index">${String(i+1).padStart(2,'0')}</div><div class="archive-caption"><small>${s.type} · ${s.date}</small><h3>${s.name}</h3><p>${s.lead}</p><div class="archive-people">${s.people.slice(0,3).map(p=>`<span>${p.name||p}</span>`).join('')}</div><b class="archive-open">打开完整事件档案 →</b></div>`;a.onclick=()=>openDetail(i);wall.append(a)});function updateArchiveProgress(){const max=wall.scrollWidth-wall.clientWidth;$('#archiveProgress').style.width=(max?20+80*wall.scrollLeft/max:100)+'%'}wall.addEventListener('scroll',updateArchiveProgress,{passive:true});wall.addEventListener('wheel',e=>{if(Math.abs(e.deltaY)>Math.abs(e.deltaX)){wall.scrollLeft+=e.deltaY;e.preventDefault()}},{passive:false});

let detailTab='origin';
function renderDetailTab(){const s=stops[activeStop],profile=s.sceneProfile,stage=$('#detailTabStage');$$('#detailTabs button').forEach(b=>b.classList.toggle('active',b.dataset.detailTab===detailTab));if(detailTab==='origin')stage.innerHTML=`<div class="origin-layout"><section class="origin-copy"><small>事件原委</small><h3>从局势到行动，不跳过中间过程</h3><p>${s.story}</p><p>${s.mechanics}</p></section><ol class="event-timeline">${s.timeline.map((t,i)=>`<li><b>${String(i+1).padStart(2,'0')}</b><div><p>${t}</p><span>${s.turning[i].replace(/^(此前|当下|此后)：/,'')}</span></div></li>`).join('')}</ol></div>`;if(detailTab==='people')stage.innerHTML=`<div class="people-archive"><div class="person-grid">${s.people.map(p=>`<article><div class="person-photo"><img src="${p.img}" alt="${p.name}人物档案影像" loading="lazy"><span>${p.note}</span></div><div><small>${p.role}</small><h3>${p.name}</h3><p>${p.bio}</p></div></article>`).join('')}</div><aside class="sacrifice-note"><small>代价与牺牲</small><h3>这里失去的，不只是一个数字</h3><p>${s.sacrifice}</p></aside></div>`;if(detailTab==='scene')stage.innerHTML=`<div class="scene-layout"><section><small>现场还原</small><h3>地形、时间与人的处境</h3><p>${s.detail}</p><p>${s.mechanics}</p></section><aside><div class="scene-condition-visual"><div class="condition-compass"><i></i><span>N</span></div><b>${profile.accent}</b><small>FIELD CONDITIONS</small><div class="condition-ridges"><i></i><i></i><i></i></div></div><div class="condition-report"><small>现场条件档案</small><h3>${s.sub}</h3><div class="condition-row"><span>地形</span><b>${profile.terrain}</b><i style="--level:82%"></i></div><div class="condition-row"><span>天候</span><b>${profile.weather}</b><i style="--level:64%"></i></div><div class="condition-row"><span>行动压力</span><b>${profile.pressure}</b><i style="--level:90%"></i></div></div></aside></div>`;if(detailTab==='impact')stage.innerHTML=`<div class="impact-layout"><section><small>因果链</small><h3>转折究竟发生在哪里</h3><div class="turning-chain">${s.turning.map((t,i)=>`<article><b>${['此前','当下','此后'][i]}</b><p>${t.replace(/^(此前|当下|此后)：/,'')}</p></article>`).join('')}</div><p class="impact-conclusion">${s.meaning}</p></section><div class="evidence-gallery text-evidence"><article><small>历史坐标</small><b>${s.date} · ${s.name}</b><p>${s.place}</p></article><article><small>历史意义</small><b>${s.sub}</b><p>${s.meaning}</p></article></div></div>`}
$$('#detailTabs button').forEach(b=>b.onclick=()=>{detailTab=b.dataset.detailTab;renderDetailTab()});
function openDetail(i){activeStop=i;detailTab='origin';const s=stops[i],profile=s.sceneProfile;$('#detailMapName').textContent=s.name;$('#detailIndex').textContent=String(i+1).padStart(2,'0');$('#detailFieldDate').textContent=s.date;$('#detailFieldSub').textContent=s.sub;$('#detailFieldTerrain').textContent=profile.terrain;$('#detailFieldWeather').textContent=profile.weather;$('#detailFieldPressure').textContent=profile.pressure;$('#detailFieldAccent').textContent=profile.accent;$('#detailDate').textContent=s.date;$('#detailCoord').textContent=`遗址附近约 ${s.lat.toFixed(2)}°N / ${s.lon.toFixed(2)}°E`;$('#detailTitle').textContent=s.name;$('#detailSubtitle').textContent=s.sub;$('#detailLead').textContent=s.lead;$('#detailSource').href=s.source;renderDetailTab();playDissolve(()=>openPanel($('#detailPanel')))}window.openDetail=openDetail;
function playDissolve(midpoint){const canvas=$('#dissolveCanvas');if(!canvas||matchMedia('(prefers-reduced-motion: reduce)').matches){midpoint();return}const ctx=canvas.getContext('2d'),dpr=Math.min(devicePixelRatio||1,2),w=innerWidth,h=innerHeight;canvas.width=w*dpr;canvas.height=h*dpr;canvas.style.display='block';ctx.setTransform(dpr,0,0,dpr,0,0);const cells=[];for(let y=-40;y<h+80;y+=92)for(let x=-40;x<w+80;x+=92)cells.push({x:x+(Math.random()-.5)*74,y:y+(Math.random()-.5)*74,r:34+Math.random()*58,delay:Math.random()*.28});let opened=false,start=performance.now();function frame(now){const p=Math.min(1,(now-start)/980);ctx.clearRect(0,0,w,h);if(p<.5){ctx.fillStyle='rgba(8,5,4,.98)';cells.forEach(c=>{const q=Math.max(0,Math.min(1,(p*2-c.delay)/(1-c.delay))),r=c.r*q*2.7;ctx.beginPath();ctx.arc(c.x,c.y,r,0,Math.PI*2);ctx.fill()})}else{if(!opened){opened=true;midpoint()}ctx.fillStyle='#080504';ctx.fillRect(0,0,w,h);ctx.globalCompositeOperation='destination-out';cells.forEach(c=>{const q=Math.max(0,Math.min(1,((p-.5)*2-c.delay)/(1-c.delay))),r=c.r*q*3.15;ctx.beginPath();ctx.arc(c.x,c.y,r,0,Math.PI*2);ctx.fill()});ctx.globalCompositeOperation='source-over';ctx.strokeStyle=`rgba(206,61,39,${Math.max(0,1-(p-.5)*3)})`;ctx.lineWidth=3;cells.slice(0,90).forEach(c=>{const q=Math.max(0,Math.min(1,((p-.5)*2-c.delay)/(1-c.delay))),r=c.r*q*3.15;if(r>2){ctx.beginPath();ctx.arc(c.x,c.y,r,0,Math.PI*2);ctx.stroke()}})}if(p<1)requestAnimationFrame(frame);else{canvas.style.display='none';ctx.clearRect(0,0,w,h)}}requestAnimationFrame(frame)}
function openPanel(p){p.classList.add('open');p.setAttribute('aria-hidden','false');$('#scrim').classList.add('show')}function closePanels(){$$('.detail-panel,.source-panel').forEach(p=>{p.classList.remove('open');p.setAttribute('aria-hidden','true')});$('#scrim').classList.remove('show')}$('#panelClose').onclick=closePanels;$('#sourceClose').onclick=closePanels;$('#scrim').onclick=closePanels;$('#detailPrev').onclick=()=>openDetail((activeStop+10)%11);$('#detailNext').onclick=()=>openDetail((activeStop+1)%11);
