scenarios.forEach((s,i)=>{const b=document.createElement('button');b.textContent=String(i+1).padStart(2,'0');b.classList.toggle('active',i===0);b.onclick=()=>renderScenario(i);$('#scenarioTabs').append(b)});function renderScenario(i){activeScenario=i;const s=scenarios[i];$$('#scenarioTabs button').forEach((b,j)=>b.classList.toggle('active',i===j));$('#decisionBg').style.backgroundImage='linear-gradient(120deg,#090605 5%,#261810 48%,#111b17 100%)';$('#decisionCard').innerHTML=`<small>${s.date}</small><h3>${s.title}</h3><p class="situation">${s.situation}</p><div class="choices">${s.choices.map((c,j)=>`<button class="choice" data-choice="${j}">${String.fromCharCode(65+j)} · ${c}</button>`).join('')}</div><div class="answer-status" aria-live="polite"></div><div class="historical-answer"><b>${s.answer}</b><p>${s.explain}</p></div>`;$$('.choice',$('#decisionCard')).forEach(b=>b.onclick=()=>{const chosen=+b.dataset.choice,correct=chosen===s.correct;$$('.choice',$('#decisionCard')).forEach((x,j)=>{x.disabled=true;x.classList.add('reveal');x.classList.toggle('correct',j===s.correct);x.classList.toggle('selected',j===chosen)});const status=$('.answer-status',$('#decisionCard'));status.className='answer-status show '+(correct?'matched':'diverged');status.innerHTML=`<b>${correct?'判断与历史选择一致':'你的选择与历史选择不同'}</b><span>你选择了 ${String.fromCharCode(65+chosen)}；当时的关键选择是 ${String.fromCharCode(65+s.correct)}。</span>`;$('.historical-answer',$('#decisionCard')).classList.add('show');$('.historical-answer',$('#decisionCard')).scrollIntoView({behavior:'smooth',block:'nearest'})})}renderScenario(0);

const relics=[{name:'草鞋',tag:'草鞋 · 行路',story:'磨穿的草鞋提醒我们：二万五千里不是数字，而是由每一步疼痛、每一次重新站起组成。'},{name:'皮带',tag:'半截皮带 · 生存',story:'草地断粮时，皮带也曾成为食物。被留下的半截皮带，是极端饥饿与把希望留给明天的见证。'},{name:'银元',tag:'一枚银元 · 军民',story:'青杠坡战斗中，负伤战士胡道财获留一枚银元疗伤。小小银元保存着战友托付与军民互助。'},{name:'船桨',tag:'船桨 · 协作',story:'皎平渡36名船工昼夜摆渡。历史的巨轮，有时正由普通人手里的一支木桨推动。'}];let relicIndex=0;relics.forEach((r,i)=>{const b=document.createElement('button');b.textContent=r.name;b.className=i===0?'active':'';b.onclick=()=>{relicIndex=i;$$('#relicPicks button').forEach((x,j)=>x.classList.toggle('active',i===j));$('#relicStory').textContent=r.story;$('#cardRelic').textContent=r.tag};$('#relicPicks').append(b)});$('#relicStory').textContent=relics[0].story;
$$('#spiritPicks button').forEach(b=>b.onclick=()=>{spirit=b.dataset.spirit;$$('#spiritPicks button').forEach(x=>x.classList.toggle('active',x===b))});function refreshCard(){const text=$('#legacyText').value.trim()||'在看不清终点时，仍走好下一步。',now=new Date();$('#cardSpirit').textContent=spirit;$('#cardRelic').textContent=relics[relicIndex].tag;$('#cardText').textContent=text;$('#cardDate').textContent=`${now.getFullYear()}.${String(now.getMonth()+1).padStart(2,'0')}.${String(now.getDate()).padStart(2,'0')}`;$('#cardNumber').textContent='NO. '+String(Math.floor(1000+Math.random()*8999));$('#legacyCard').classList.remove('generated');void $('#legacyCard').offsetWidth;$('#legacyCard').classList.add('generated')}$('#generateCard').onclick=refreshCard;
function wrap(ctx,text,x,y,maxWidth,lineHeight){const chars=[...text];let line='',lines=[];for(const ch of chars){if(ctx.measureText(line+ch).width>maxWidth){lines.push(line);line=ch}else line+=ch}if(line)lines.push(line);lines.slice(0,4).forEach((l,i)=>ctx.fillText(l,x,y+i*lineHeight))}
const cardBackground=new Image();cardBackground.src='assets/card-longmarch-bg.png';
$('#downloadCard').onclick=async()=>{const btn=$('#downloadCard');btn.disabled=true;btn.textContent='正在生成纪念卡…';refreshCard();try{if(!cardBackground.complete||!cardBackground.naturalWidth)await cardBackground.decode();const c=$('#cardCanvas'),x=c.getContext('2d');x.clearRect(0,0,1200,1600);x.drawImage(cardBackground,0,0,1200,1600);const veil=x.createLinearGradient(0,0,0,1600);veil.addColorStop(0,'rgba(239,225,195,.08)');veil.addColorStop(.42,'rgba(239,225,195,.76)');veil.addColorStop(.78,'rgba(239,225,195,.88)');veil.addColorStop(1,'rgba(31,21,15,.55)');x.fillStyle=veil;x.fillRect(0,0,1200,1600);x.strokeStyle='rgba(48,33,23,.55)';x.lineWidth=3;x.strokeRect(54,54,1092,1492);x.fillStyle='#2b1d15';x.font='32px Space Grotesk';x.fillText('LONG MARCH · 2026',90,112);x.textAlign='right';x.fillText($('#cardNumber').textContent,1110,112);x.textAlign='left';x.strokeStyle='#7c2c23';x.beginPath();x.moveTo(90,150);x.lineTo(1110,150);x.stroke();x.fillStyle='#8f2b22';x.font='700 34px "Noto Serif SC"';x.fillText(relics[relicIndex].tag,95,690);x.fillStyle='#2c2017';x.font='36px "Noto Serif SC"';x.fillText('我的精神坐标',95,785);x.fillStyle='#a42a20';x.font='900 245px "Noto Serif SC"';x.fillText(spirit,85,1060);x.fillStyle='#251a13';x.font='700 50px "Noto Serif SC"';wrap(x,$('#legacyText').value.trim()||'在看不清终点时，仍走好下一步。',95,1190,880,72);x.strokeStyle='#9d2b22';x.lineWidth=9;x.beginPath();x.arc(970,320,112,0,Math.PI*2);x.stroke();x.save();x.translate(970,320);x.rotate(.18);x.textAlign='center';x.textBaseline='middle';x.fillStyle='#9d2b22';x.font='800 112px "Noto Serif SC"';x.fillText('征',0,0);x.restore();x.fillStyle='#efe2c8';x.font='28px Space Grotesk';x.fillText('从历史深处出发',95,1510);x.textAlign='right';x.fillText($('#cardDate').textContent,1110,1510);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw new Error('canvas export failed');const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='我的长征精神纪念卡.png';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);btn.textContent='✓ 已生成并下载'}catch(e){console.error(e);btn.textContent='下载失败，请重试'}finally{setTimeout(()=>{btn.disabled=false;btn.textContent='↓ 下载纪念卡 PNG'},2200)}};

const rollcalls=[
 {title:'陈树湘与红三十四师',meta:'湘江 · 1934',text:'为掩护中央纵队渡江，红三十四师承担后卫任务，大部壮烈牺牲。师长陈树湘以生命践行忠诚。'},
 {title:'邓萍',meta:'娄山关 · 1935',text:'红三军团参谋长，在遵义战役前线侦察时牺牲，年仅二十七岁。胜利的背面，是未能看到胜利的人。'},
 {title:'皎平渡36名船工',meta:'金沙江 · 1935',text:'七只木船昼夜往返九天九夜。普通船工用木桨，把数万人的命运送向北岸。'},
 {title:'泸定桥22名突击队员',meta:'大渡河 · 1935',text:'他们共同攀上冰冷铁索。部分姓名留存，部分湮没于岁月；集体的勇气却越过了河流。'},
 {title:'“云贵川”',meta:'腊子口 · 1935',text:'带队攀上峭壁、打开侧后通道的战士，真实姓名至今仍有争议。无名并不意味着被历史遗忘。'},
 {title:'雪线上的互助者',meta:'夹金山 · 1935',text:'他们让出衣物、食物，搀扶掉队者。许多名字没有被记录，但战友走下雪山，就是他们留下的答案。'},
 {title:'草地收容队',meta:'松潘草地 · 1935',text:'他们走在队伍最后，寻找伤病员与掉队者。在没有道路的沼泽里，“不放弃一个人”本身就是方向。'},
 {title:'红二十五军战士',meta:'陕甘 · 1935',text:'他们以不足三千人的队伍转战数省，牵制敌军，先期到达陕北，为主力北上提供策应。'},
 {title:'千千万万无名者',meta:'二万五千里 · 1934—1936',text:'炊事员、担架员、卫生员、通信员、船工、向导与沿途群众——他们共同的名字，叫作人民。'}
];
const rollEchoes=['湘江的牺牲使全党全军不得不直面军事指挥问题。忠诚不是拒绝反思，而是用真实代价推动道路转变。','他的牺牲发生在胜利即将到来之前。历史因此提醒后来者：每一个转折点，都有人把自己留在了前夜。','没有他们的木船与体力，战略部署无法变成现实。军民之间的信任，是红军跨越天险的重要力量。','桥上的冲锋与桥后的铺板、掩护共同完成突破。个人勇敢只有进入集体协同，才能真正改变战局。','名字或许模糊，行动却留下清晰方向：当正面道路被封死，创造性与胆识能从绝壁上打开通道。','雪山上的互助把“活下去”变成共同命题。长征精神最沉重的部分，常发生在无人记录的相互搀扶里。','他们守住队伍最后的生命线。对伤员与掉队者的寻找，让“一个队伍”不只是行军序列，更是共同体。','这支先期抵达陕北的力量为长征落脚创造条件。每一路远征都不是孤立的，最终汇聚成新的革命力量。','无数普通人的选择共同托起了长征。历史真正的主角，不只是被写进名字的人，也是人民本身。'];
const rollFacts=[['1905—1934','红三十四师师长','后卫阻击 · 湘江'],['1908—1935','红三军团参谋长','前线侦察 · 遵义战役'],['36名当地船工','七只木船','九天九夜 · 金沙江'],['22名突击队员','红四团夺桥先锋','铁索突击 · 大渡河'],['姓名仍待考证','侧翼攀岩突击者','夜袭天险 · 腊子口'],['无数普通战士','衣物与食物互助','高海拔雪线 · 夹金山'],['炊事班与卫生收容力量','行军队尾生命线','沼泽与饥饿 · 松潘草地'],['不足三千人的转战队伍','先期抵达陕北','策应北上 · 陕甘'],['没有完整名册','战士、船工、向导、群众','共同完成 · 二万五千里']];
let rollIndex=0,rollTimer;function renderRoll(i){rollIndex=(i+rollcalls.length)%rollcalls.length;const r=rollcalls[rollIndex],facts=rollFacts[rollIndex];$('#rollIndex').textContent=`${String(rollIndex+1).padStart(2,'0')} / ${String(rollcalls.length).padStart(2,'0')}`;$('#rollStage').innerHTML=`<small>${r.meta}</small><h3>${r.title}</h3><p>${r.text}</p><div class="roll-facts">${facts.map((f,j)=>`<span><small>${['身份 / 规模','承担的任务','历史坐标'][j]}</small><b>${f}</b></span>`).join('')}</div><div class="roll-echo"><b>历史回声</b><p>${rollEchoes[rollIndex]}</p></div>`;$('#rollProgress').style.width=`${(rollIndex+1)/rollcalls.length*100}%`;clearTimeout(rollTimer);if(currentRoom==='finale')rollTimer=setTimeout(()=>renderRoll(rollIndex+1),9000)}$('#rollPrev').onclick=()=>renderRoll(rollIndex-1);$('#rollNext').onclick=()=>renderRoll(rollIndex+1);renderRoll(0);

let audioCtx,audioMaster,audioOn=false,audioBuilt=false;
function softPulse(){if(!audioCtx)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain(),t=audioCtx.currentTime;o.type='sine';o.frequency.setValueAtTime(58,t);o.frequency.exponentialRampToValueAtTime(44,t+.55);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.026,t+.04);g.gain.exponentialRampToValueAtTime(.0001,t+.55);o.connect(g).connect(audioMaster);o.start(t);o.stop(t+.58);setTimeout(softPulse,2600+Math.random()*2600)}
function buildAudio(){audioCtx=new (window.AudioContext||window.webkitAudioContext)();audioMaster=audioCtx.createGain();audioMaster.gain.value=.14;audioMaster.connect(audioCtx.destination);const buffer=audioCtx.createBuffer(1,audioCtx.sampleRate*4,audioCtx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;const wind=audioCtx.createBufferSource(),filter=audioCtx.createBiquadFilter(),windGain=audioCtx.createGain();wind.buffer=buffer;wind.loop=true;filter.type='lowpass';filter.frequency.value=520;windGain.gain.value=.075;wind.connect(filter).connect(windGain).connect(audioMaster);wind.start();[49,73.5].forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=f;g.gain.value=i?.018:.028;o.connect(g).connect(audioMaster);o.start()});softPulse();audioBuilt=true}
function setSoundScene(){}
function startAudio(){if(!audioBuilt)buildAudio();audioCtx.resume();audioMaster.gain.setTargetAtTime(.14,audioCtx.currentTime,.25);audioOn=true;$('#soundBtn').classList.add('on');$('#soundBtn b').textContent='声场'}$('#soundBtn').onclick=()=>{if(!audioBuilt){startAudio();return}audioOn=!audioOn;audioMaster.gain.setTargetAtTime(audioOn?.14:.0001,audioCtx.currentTime,.2);$('#soundBtn').classList.toggle('on',audioOn);$('#soundBtn b').textContent=audioOn?'声场':'静音'};
document.addEventListener('keydown',e=>{if(e.key==='Escape')closePanels();if(e.key==='ArrowRight'&&!$('#detailPanel').classList.contains('open')){const order=['prologue','route','archive','decision','legacy','finale'];showRoom(order[Math.min(5,order.indexOf(currentRoom)+1)])}if(e.key==='ArrowLeft'&&!$('#detailPanel').classList.contains('open')){const order=['prologue','route','archive','decision','legacy','finale'];showRoom(order[Math.max(0,order.indexOf(currentRoom)-1)])}});
